parameters.text:
={{ (() => {
  const o = $('Features creator').first().json.output;
  if (o.includes('FEATURE_NEXT')) return o.split('FEATURE_NEXT')[1].trim();
  if (o.includes('FEATURE_VALIDATED')) return o.trim().split(/\n\n/).pop();
  return o;
})() }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "id": {
      "type": "integer",
      "description": "Identifier of the feature, the number after 'ID :' under the priority line."
    },
    "title": {
      "type": "string",
      "description": "Feature title verbatim, from the '# ' heading, without the '#'."
    },
    "priority": {
      "type": "string",
      "enum": [
        "Highest",
        "High",
        "Medium",
        "Low",
        "Lowest"
      ]
    },
    "description": {
      "type": "string",
      "description": "Sections '## Valeur' and '## Règles produit' verbatim, markdown included. Without the title, the priority line, the ID line, the marker and the stories."
    },
    "stories": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": [
              "integer",
              "null"
            ],
            "description": "Identifier of an existing story, the number after 'ID :' at the end of its line; null for a new story."
          },
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "priority": {
            "type": "string",
            "enum": [
              "Highest",
              "High",
              "Medium",
              "Low",
              "Lowest"
            ]
          }
        },
        "required": [
          "title",
          "description",
          "priority"
        ]
      }
    }
  },
  "required": [
    "id",
    "title",
    "priority",
    "description",
    "stories"
  ]
}
